const pipeline = (x) => x();

const importers = [
  async (path) => {
    if (!/^\.[\\/](?:libs\/dcx-ng-lib\/src\/lib\/stories(?:\/(?!\.)(?:(?:(?!(?:^|\/)\.).)*?)\/|\/|$)(?!\.)(?=.)[^/]*?\.stories\.ts)$/.exec(path)) {
      return;
    }
  
    const pathRemainder = path.substring(34);
    return import(
      /* webpackChunkName: "[request]" */
      /* webpackInclude: /(?!.*node_modules)(?:\/libs\/dcx-ng-lib\/src\/lib\/stories(?:\/(?!\.)(?:(?:(?!(?:^|\/)\.).)*?)\/|\/|$)(?!\.)(?=.)[^/]*?\.stories\.ts)$/ */
      './libs/dcx-ng-lib/src/lib/stories/' + pathRemainder
    );
  }
  
];

export async function importFn(path) {
  for (let i = 0; i < importers.length; i++) {
    const moduleExports = await pipeline(() => importers[i](path));
    if (moduleExports) {
      return moduleExports;
    }
  }
}